theorem intent_antitone {O A : Type*} (R : O → A → Prop) {O₁ O₂ : Set O}
    (h : O₁ ⊆ O₂) :
    intent R O₂ ⊆ intent R O₁

theorem extent_antitone {O A : Type*} (R : O → A → Prop) {B₁ B₂ : Set A}
    (h : B₁ ⊆ B₂) :
    extent R B₂ ⊆ extent R B₁

lemma sum_eq_card_mul_mean {α : Type*} [Fintype α] {X : α → ℝ} {μ : ℝ}
    (hN : 0 < Fintype.card α) (hmean : uniformExpectation X = μ) :
    (∑ x : α, X x) = (Fintype.card α : ℝ) * μ

theorem hoeffding_lemma {α : Type*} [Fintype α] {X : α → ℝ} {lam : ℝ}
    (hN : 0 < Fintype.card α) (hzero : (∑ x : α, X x) = 0) (hb : ∀ x : α, |X x| ≤ 1) :
    uniformExpectation (fun x => Real.exp (lam * X x)) ≤ Real.exp (lam ^ 2 / 2)
